                  csrw 0x3b9, x2
                  li x2, 0x8e100090
                  csrw 0x3a2, x2
                  li x2, 0x1b0003b6
                  csrw 0x3be, x2
                  li x2, 0x594cf46
                  csrw 0x3bf, x2
                  li x2, 0x850f1e0e
                  csrw 0x3a3, x2
                  csrwi 0x747, 1

mepc_setup:       
                  la x10, init
                  csrw 0x341, x10

custom_csr_setup: 
                  csrwi 0x7c0, 1

init_machine_mode:
                  li x10, 0x21800
                  csrw 0x300, x10 # MSTATUS
                  li x10, 0x0
                  csrw 0x304, x10 # MIE
                  li x29, 0x8ffffffc
                  li x10, 0x300
                  slli x10, x10, 8
                  addi x10, x10, 0x3
                  sw x10, 0(x29)
                  csrr x10, 0x300
                  sw x10, 0(x29)
                  li x29, 0x8ffffffc
                  li x10, 0x304
                  slli x10, x10, 8
                  addi x10, x10, 0x3
                  sw x10, 0(x29)
                  csrr x10, 0x304
                  sw x10, 0(x29)
                  mret
init:             
                  li x0, 0x0
                  li x1, 0x0
                  li x2, 0xf55ae986
                  li x3, 0x80000000
                  li x4, 0x6
                  li x5, 0x3
                  li x6, 0xf4f77d4b
                  li x7, 0xb
                  li x8, 0x2e3a97b
                  li x9, 0x2
                  li x10, 0xd3867231
                  li x11, 0x304a526d
                  li x13, 0xa4a7ca8
                  li x14, 0x0
                  li x15, 0x0
                  li x16, 0x80000000
                  li x17, 0x80000000
                  li x18, 0x73c42ca1
                  li x19, 0x0
                  li x20, 0x8cbc6cda
                  li x21, 0xc
                  li x22, 0x80000000
                  li x23, 0x0
                  li x24, 0x0
                  li x25, 0x0
                  li x27, 0x35fbfb61
                  li x28, 0xfcf45d11
                  li x29, 0x5
                  li x30, 0xd
                  li x31, 0xfd54d360
                  la x26, user_stack_end
                  li x29, 0x8ffffffc
                  li x10, 0x0
                  slli x10, x10, 8
                  addi x10, x10, 0x0
                  sw x10, 0(x29)
                  j main
test_done:        
                  li x29, 0x8ffffff8
                  li x10, 0x0
                  slli x10, x10, 8
                  addi x10, x10, 0x1
                  sw x10, 0(x29)
                  ecall

test_fail:        
                  li x29, 0x8ffffff8
                  li x10, 0x1
                  slli x10, x10, 8
                  addi x10, x10, 0x1
                  sw x10, 0(x29)
                  ecall

